(31120, 'Section 14', '', 2567, 8, 31118, 0, 0, 2, 0, 0, 424797, 0, 3, 4128, 0, 59888),
(31118, 'Section 12', '$[!23\n\nOn Mythic difficulty, Chaotic Corruption applies Chaotic Vulnerability to the player upon removal.$]', 2567, 7, 0, 31120, 27557, 2, 0, 0, 424739, 0, 3, 4128, 0, 59888),
