(21582, 'Dessia the Decapitator', '', 2397, 7, 0, 21585, 21581, 1, 95391, 0, 0, 0, 0, 0, -1, 59888),
(21581, 'Paceran the Virulent', '', 2397, 10, 0, 21588, 21591, 1, 90638, 0, 0, 0, 0, 0, -1, 59888),
(21580, 'Damage Dealers', '$bullet;When defeated, the fallen challenger grants the remaining challengers |cFF2959D3|Hspell:1215747|h[Final Will]|h|r.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.\n$bullet;Upon reaching 100 energy, Paceran targets players with |cFF2959D3|Hspell:320182|h[Noxious Spores]|h|r.', 2397, 4, 21577, 0, 21579, 3, 0, 0, 0, 0, 2, 2, 0, 59888),
(21579, 'Healer', '$bullet;|cFF2959D3|Hspell:320069|h[Mortal Strike]|h|r reduces all healing taken.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.\n$bullet;|cFF2959D3|Hspell:1215600|h[Withering Touch]|h|r continuously inflicts Shadow damage to target players until it is dispelled.', 2397, 5, 21577, 0, 0, 3, 0, 0, 0, 0, 0, 4, -1, 59888),
(21577, 'Overview', 'Defeat all three challengers to prove your worth.  Each challenger unleashes a powerful ability when they reach 100 energy.', 2397, 1, 0, 22650, 31257, 3, 0, 0, 0, 0, 0, 0, -1, 59888),
(19233, 'Tanks', '$bullet;Bring the Platinum Pummeler within range of |cFF2959D3|Hspell:282943|h[Piston Smashers]|h|r to remove stacks of |cFF2959D3|Hspell:282801|h[Platinum Plating]|h|r', 2336, 2, 19232, 0, 19234, 3, 0, 0, 0, 0, 0, 1, -1, 59888);
