INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Meeksi Teatuft', '|cFFFFD200In-Game Shop|r|n', 'Teatufts are known for their aromatic teas. However, their playful nature can result in an excess of spilled tea.', 2345, 424, 64, 9, 473744, 0, 0, 4, 0, 0, 59888),
('Meeksi Rollingpaw', '|cFFFFD200In-Game Shop|r|n', 'Rollingpaws are very proud of their tea bearing duties. They are always willing to provide a warm cup of tea to their travelling companions.', 2344, 424, 64, 9, 473743, 0, 0, 4, 0, 0, 59888),
('Meeksi Softpaw', '|cFFFFD200In-Game Shop|r|n', 'Softpaws provide a black tea that is ideal for an early morning jolt or staying awake late into the night.', 2343, 424, 64, 9, 473741, 0, 0, 4, 0, 0, 59888),
('Meeksi Rufflefur', '|cFFFFD200In-Game Shop|r|n', 'Rufflefurs are playful, clumsy and obsessed with cleanliness. This is a dangerous combination of traits.', 2342, 424, 64, 9, 473739, 0, 0, 4, 0, 0, 59888),
('Pearlescent Butterfly', '|cFFFFD200Trading Post|r', 'Take to the skies on a glittering, shimmering, pearlescent butterfly.', 2489, 424, 64, 11, 1217994, 0, 0, 4, 0, 0, 59888),
('Personalized Goblin S.C.R.A.P.per', '|cFFFFD200Drop:|r Sifted Pile of Scrap|n|cFFFFD200Zone:|r Undermine', 'Goblin Shredders have proven time and again to be useful in many applications, such as in logging and transportation. This model has been repurposed for use by S.C.R.A.P..', 2288, 230, 0, 0, 466020, 0, 0, 4, 0, 0, 59888),
('Meeksi Brewthief', '|cFFFFD200In-Game Shop|r|n', 'Despite their mischievous and playful nature, these creatures make for loyal and dependable travelling companions.', 2346, 424, 64, 9, 473745, 0, 0, 4, 0, 0, 59888),
('Delver\'s Gob-Trotter', '|cFFFFD200World Quest: |rI Want My Hat Back|n|cFFFFD200Zone: |rIsle of Dorn|n|cFFFFD200Zone: |rDornogal', 'This aircraft will help you delve straight into adventure, if it doesn\'t explode!', 2296, 402, 512, 1, 466133, 0, 0, 920, 0, 0, 59888),
('Thunderdrum Misfire', '|cFFFFD200Vendor: |rAndo the Gat|n|cFFFFD200Zone: |rLiberation of Undermine|n|cFFFFD200Cost: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Recovered from the Cauldron\'s bleachers during a particularly gruesome clash. When asked if it was a dud, Torq\'s operator simply replied: \'Probably?\'', 2279, 424, 0, -1, 466012, 0, 0, 4, 0, 0, 59888),
('Darkfuse Chompactor', '|cFFFFD200Vendor: |rAndo the Gat|n|cFFFFD200Zone: |rLiberation of Undermine|n|cFFFFD200Cost: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Considered the Top Dog among Stix\'s Junkyard Hyenas, it boasts a bite force strong enough to crush whatever - or whoever - Gallywix wants disposed of.', 2276, 230, 0, -1, 466000, 0, 0, 4, 0, 0, 59888),
('Vengeance', '|cFFFFD200Drop:|r Lady Sylvanas Windrunner|n|cFFFFD200Zone:|r Sanctum of Domination|n|cFFFFD200Difficulty:|r Mythic', 'Sylvanas lost a part of herself the day Arthas took her life, and the darkness within her grew to fill the void.', 1471, 424, 128, 6, 351195, 0, 0, 4, 0, 0, 59888);
